def f(items):
    """Returns the number of contiguous subarrays whose sum is zero."""
    prefix = 0
    counts = {0: 1}
    total = 0

    for x in items:
        prefix += x
        total += counts.get(prefix, 0)
        counts[prefix] = counts.get(prefix, 0) + 1

    return total
